; One question entry (14 bytes):
;   quizq QUESTION, CORRECT_INDEX(0-3), NUM_ANSWERS(2-4), ANS0, ANS1, ANS2, ANS3, HINT
MACRO quizq
	dw \1
	db \2
	db \3
	dw \4, \5, \6, \7
	dw \8
ENDM

