; ---- result messages (shown via PrintText) ----
QuizCorrectText::
	text "Great job!"
	line "Streak "
	text_ram wStringBuffer
	prompt

QuizTryAgainText::
	text "Hint:"
	line ""
	text_ram wStringBuffer
	cont "Try once more!"
	prompt

QuizMissText::
	text "The answer was"
	line ""
	text_ram wStringBuffer
	cont "Now you know!"
	prompt

